exercises.solution:
cat > start-lokalny.sh <<'KONIEC'
#!/bin/bash
JAVA_OPTS=${JAVA_OPTS:--Xmx512m -Dspring.profiles.active=dev}
JAR=${JAR:-sklep.jar}
# shellcheck disable=SC2086  # JAVA_OPTS celowo dzielone na opcje (bez spacji w wartosciach)
echo java $JAVA_OPTS -jar "$JAR" "$@"
KONIEC
shellcheck start-lokalny.sh && echo "brak uwag"
sed '/disable=SC2086/d' start-lokalny.sh > start-bez-dyrektywy.sh
shellcheck start-bez-dyrektywy.sh | grep -oE 'SC[0-9]+ \([a-z]+\)'
